    public static void main(String[] args) {
        String[] stages = {"compile", "verify", "release"};
        boolean[] results = {true, true, false};
        for (int i = 0; i < stages.length; i++) {
            if (!results[i]) {
                System.out.println("Стоп: " + stages[i]);
                break;
            }
        }
    }
}

